"""parche-89: AUTOEXAMEN. En vez de que yo escriba preguntas una a una, scripts/autoexamen.py GENERA un examen de dialogo con nombres/cosas/ciudades al azar
y varias formas de preguntar lo mismo (que/quien/donde, si/no, correccion con "No,", profesion, padre, nombre, comparar, aritmetica), lo pasa por la
conversacion real y agrupa los fallos por FAMILIA. check.py lo ejecuta (informativo, semilla fija 101) y el informe muestra el desglose por familia:
asi veo en tu paquete que tipo de pregunta no se cubre y lo arreglo por familias, no por frase. Regenera data/autoexamen.tsv (fichero generado).
Cambio de comportamiento: ninguno. Criterio: 96 tests pasan (94 + 2) y nada baja. Uso: python -m scripts.ciclo parche-89.py
Tambien puedes probar otra semilla:  python -m scripts.autoexamen --semilla 7 --n 30"""
import datetime, py_compile, shutil, sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
ALL_EDITS = [('scripts/check.py', '    hist_path = "reports/historial.json"\n', '    from scripts.autoexamen import ejecutar as _auto                           # parche-89: examen generado (informativo, semilla fija)\n    try:\n        _g, _t, _bad3, _res, _tags = _auto(10, 101)\n        metrics[f"autoexamen_{_t}"] = round(_g / max(_t, 1), 4)\n        log(f"\\nautoexamen_{_t}: {_g}/{_t} = {_g / max(_t, 1):.1%}  (informativo)")\n        for _k, (_ok, _tot) in _res.items():\n            log(f"   familia {_k:16s} {_ok}/{_tot}")\n        for _turn, _exp, _ans in _bad3[:40]:\n            log(f"   FALLO [{_tags.get(_turn, \'?\')}] {_turn!r} esperado={_exp} obtenido={_ans[:100]!r}")\n\n    except Exception as _e:\n        log(f"\\nautoexamen: no se pudo ejecutar ({_e!r})")\n\n    hist_path = "reports/historial.json"\n', 'parche-89: examen generado')]
NEW_FILES = {'scripts/autoexamen.py': '"""Autoexamen (parche-89): genera cada vez un examen de dialogo NUEVO a partir de plantillas con nombres/cosas/ciudades al azar y VARIAS formas de\npreguntar lo mismo, lo pasa por la conversacion real y agrupa los fallos por plantilla. Es el bucle \'generar -> intentar -> agrupar fallos\' sin que\ntengas que escribir preguntas: los fallos de reports/informe.txt dicen QUE FAMILIA de pregunta no se cubre.\nUso:  python -m scripts.autoexamen [--semilla 101] [--n 10]     (check.py lo ejecuta con semilla fija como examen informativo)"""\nimport argparse\nimport random\nfrom collections import defaultdict\n\nFEM = ["Ana", "Marta", "Rosa", "Elena", "Sara", "Clara", "Irene", "Lucia", "Nora", "Julia", "Paula", "Carla"]\nMAS = ["Pedro", "Luis", "Juan", "Carlos", "Pablo", "Raul", "Hugo", "Mario", "Tomas", "Diego", "Andres", "Ivan"]\nCOSAS = ["pan", "leche", "flores", "naranjas", "cafe", "manzanas", "queso", "arroz"]\nCIUDADES = ["Madrid", "Sevilla", "Lugo", "Bilbao", "Cuenca", "Valencia", "Cadiz", "Leon", "Burgos", "Granada"]\nPROFES = [("profesora", "profesor"), ("medica", "medico"), ("abogada", "abogado"), ("pintora", "pintor"), ("ingeniera", "ingeniero"), ("cantante", "cantante")]\n\n\ndef _blocks(rng, n):\n    """Devuelve lista de (tag, [(turno, esperado)])."""\n    out = []\n    for _ in range(n):\n        f = rng.sample(FEM, 3)\n        m = rng.sample(MAS, 2)\n        c = rng.sample(CIUDADES, 2)\n        t = rng.choice(COSAS)\n        pf, pm = rng.choice(PROFES)\n        a, b = rng.randint(2, 12), rng.randint(2, 12)\n        out.append(("compra_que", [(f"{f[0]} compra {t}.", ""), (rng.choice([f"¿Qué compra {f[0]}?", f"¿Qué es lo que compra {f[0]}?", f"Dime qué compra {f[0]}"]), t)]))\n        out.append(("compra_quien", [(f"{m[0]} compra {t}.", ""), (rng.choice([f"¿Quién compra {t}?", f"¿Quién es el que compra {t}?"]), m[0])]))\n        out.append(("compra_si", [(f"{f[1]} compra {t}.", ""), (rng.choice([f"¿Compra {f[1]} {t}?", f"¿{f[1]} compra {t}?"]), "Sí")]))\n        out.append(("vive_donde", [(f"{m[1]} vive en {c[0]}.", ""), (rng.choice([f"¿Dónde vive {m[1]}?", f"¿En qué ciudad vive {m[1]}?", f"¿Sabes dónde vive {m[1]}?"]), c[0])]))\n        out.append(("vive_quien", [(f"{f[2]} vive en {c[1]}.", ""), (rng.choice([f"¿Quién vive en {c[1]}?", f"¿Quién es la que vive en {c[1]}?"]), f[2])]))\n        out.append(("correccion", [(f"{m[0]} vive en {c[0]}.", ""), (f"No, {m[0]} vive en {c[1]}.", ""), (f"¿Dónde vive {m[0]}?", c[1]), (f"¿Dónde vivía {m[0]}?", c[0])]))\n        out.append(("profesion_que", [(f"{f[0]} es {pf}.", ""), (rng.choice([f"¿Qué es {f[0]}?", f"¿A qué se dedica {f[0]}?", f"¿De qué trabaja {f[0]}?"]), pf)]))\n        out.append(("profesion_quien", [(f"{m[1]} es {pm}.", ""), (rng.choice([f"¿Quién es {pm}?", f"¿Quién es el {pm}?"]), m[1])]))\n        out.append(("padre", [(f"{m[0]} es el padre de {f[1]}.", ""), (rng.choice([f"¿Quién es el padre de {f[1]}?", f"¿Quién es el papá de {f[1]}?"]), m[0])]))\n        out.append(("nombre", [(rng.choice([f"Me llamo {m[1]}.", f"Soy {m[1]}."]), ""), (rng.choice(["¿Cómo me llamo?", "¿Sabes cómo me llamo?", "¿Cuál es mi nombre?"]), m[1])]))\n        if rng.random() < 0.5:\n            q = (f"¿Es {f[0]} más alta que {f[2]}?", "Sí")\n        else:\n            q = (f"¿Quién es más alta, {f[0]} o {f[2]}?", f[0])\n        out.append(("comparar", [(f"{f[0]} es más alta que {f[1]}.", ""), (f"{f[1]} es más alta que {f[2]}.", ""), q]))\n        out.append(("aritmetica", [(rng.choice([f"¿Cuánto es {a} por {b}?", f"{a} x {b}", f"¿Cuánto da {a} por {b}?"]), str(a * b))]))\n    return out\n\n\ndef generar(n=10, semilla=101):\n    """-> (texto del examen en formato de dialogo, {turno: tag})."""\n    rng = random.Random(semilla)\n    lines, tags = [f"# Autoexamen generado (semilla {semilla}, {n} rondas): NO editar a mano, se regenera."], {}\n    for tag, turns in _blocks(rng, n):\n        for turn, exp in turns:\n            lines.append(f"U: {turn}\\t{exp}")\n            if exp:\n                tags[turn] = tag\n        lines.append("")\n    return "\\n".join(lines) + "\\n", tags\n\n\ndef ejecutar(n=10, semilla=101, path="data/autoexamen.tsv"):\n    from scripts.eval_dialogo import run as run_dialogo\n    text, tags = generar(n, semilla)\n    open(path, "w", encoding="utf-8").write(text)\n    g, t, bad = run_dialogo(path)\n    por = defaultdict(lambda: [0, 0])\n    for line in text.splitlines():\n        if line.startswith("U:") and "\\t" in line:\n            turn, _, exp = line[2:].strip().partition("\\t")\n            if exp.strip():\n                por[tags.get(turn.strip(), "?")][1] += 1\n    for turn, exp, ans in bad:\n        por[tags.get(turn, "?")][0] += 1\n    resumen = {k: (v[1] - v[0], v[1]) for k, v in sorted(por.items())}\n    return g, t, bad, resumen, tags\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--semilla", type=int, default=101)\n    ap.add_argument("--n", type=int, default=10)\n    a = ap.parse_args()\n    g, t, bad, resumen, tags = ejecutar(a.n, a.semilla)\n    print(f"autoexamen: {g}/{t} = {g / max(t, 1):.1%}")\n    for k, (ok, tot) in resumen.items():\n        print(f"  {k:16s} {ok}/{tot}")\n    for turn, exp, ans in bad[:60]:\n        print(f"   FALLO [{tags.get(turn, \'?\')}] {turn!r} esperado={exp} obtenido={ans[:90]!r}")\n\n\nif __name__ == "__main__":\n    main()\n', 'tests/test_parche89.py': '"""parche-89: el autoexamen es determinista y esta bien formado."""\nfrom scripts.autoexamen import generar\n\n\ndef test_autoexamen_determinista_y_bien_formado():\n    a, ta = generar(3, 5)\n    b, tb = generar(3, 5)\n    assert a == b and ta == tb\n    assert generar(3, 6)[0] != a\n    assert any(l.startswith("U: ") and "\\t" in l for l in a.splitlines())\n    assert set(ta.values()) >= {"compra_que", "vive_donde", "aritmetica", "comparar"}\n\n\ndef test_aritmetica_esperada_coincide_con_la_habilidad():\n    from src.language import skills\n    import re\n    txt, tags = generar(6, 9)\n    for turn, tag in tags.items():\n        if tag == "aritmetica":\n            exp = [l for l in txt.splitlines() if l.startswith("U: " + turn + "\\t")][0].split("\\t")[1]\n            nums = [int(x) for x in re.findall(r"\\d+", turn)]\n            assert str(nums[0] * nums[1]) == exp\n'}

def main(root: Path = ROOT) -> int:
    stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")
    bk = root / ".parche_backups" / stamp
    texts, changed = {}, set()
    for rel, old, new, marca in ALL_EDITS:                              # comprobar TODO antes de escribir nada
        p = root / rel
        if not p.is_file():
            print(f"FALTA {rel}: no se toca nada."); return 1
        txt = texts[rel] if rel in texts else p.read_text(encoding="utf-8")
        if marca in txt:
            texts[rel] = txt; continue
        if txt.count(old) != 1:
            print(f"ERROR {rel}: un trozo a cambiar aparece {txt.count(old)} veces (debe ser 1): {old[:70]!r}. No se toca nada."); return 1
        texts[rel] = txt.replace(old, new); changed.add(rel)
    plan = [(root / rel, rel, texts[rel]) for rel in sorted(changed)]
    for rel, content in NEW_FILES.items():
        p = root / rel
        if not p.exists() or p.read_text(encoding="utf-8") != content:
            plan.append((p, rel, content))
    for p, rel, txt in plan:
        if p.exists():
            (bk / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(p, bk / rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(txt, encoding="utf-8")
        if rel.endswith(".py"):
            py_compile.compile(str(p), doraise=True)
        print(f"  escrito {rel}")
    print(f"parche-89 instalado. Copias en {bk}" if plan else "parche-89: nada que hacer.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

